def count_ones(n):
    n = n & 0xFFFFFFFF
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count


def is_power_of_two(n):
    return n > 0 and (n & (n - 1)) == 0


def next_power_of_two(n):
    if n <= 1:
        return 1
    p = 1
    while p < n:
        p <<= 1
    return p


def swap_nibbles(byte):
    return ((byte & 0x0F) << 4) | ((byte & 0xF0) >> 4)
